mapper.select:
SELECT treat_type as type, COUNT(1) AS count FROM treat_mgmt WHERE deleted = 0
AND apply_time between #{startTime} and #{endTime}
GROUP BY treat_type

SELECT s.grade AS name, COUNT(1) AS value FROM treat_mgmt AS t LEFT JOIN student_info AS s ON t.student_id = s.id WHERE t.deleted = 0
AND s.grade = #{grade}
AND t.apply_time between #{startTime} and #{endTime}
